//! The marker table: the single, version-aware source of truth about USFM markers.
//!
//! Version differences (3.1 vs 3.2), serialization mappings (USX element / USJ
//! type), closing discipline, and the vref `text_role` are all *data* here, not
//! branches in the parser's hot loop. The parser interns each marker name to a
//! [`MarkerId`] once; every later stage (lint, USX, USJ, vref) reads
//! [`MarkerInfo`] by id in O(1).
//!
//! The per-version tables are generated by `build.rs` from `data/markers.toml`
//! into `$OUT_DIR/marker_tables.rs` (included at the bottom of this file): a
//! `&[MarkerInfo]` slice plus a `phf` perfect-hash `name -> id` map per version.

/// Interned identifier for a marker *type* within a given [`MarkerTable`].
///
/// Not stable across versions/tables — it is an index into one table's slice.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct MarkerId(pub u16);

impl MarkerId {
    /// Sentinel for a marker that is syntactically a marker but not in the table
    /// for the active version. It still parses (error-tolerant); the literal name
    /// is recoverable from the node's span.
    pub const UNKNOWN: MarkerId = MarkerId(u16::MAX);
}

/// Broad structural family of a marker. Drives tree shape and serialization.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Category {
    Identification, // \id, \ide, \h, \toc#
    Chapter,        // \c
    Verse,          // \v
    Paragraph,      // \p, \q#, \m, \b ...
    Character,      // \add, \nd, \w, \k ... (inline, paired)
    Note,           // \f, \x, \fe (paired, content excluded from vref text)
    Milestone,      // \qt-s\*, \ts-s\* ...
    Other,
}

impl Category {
    pub fn as_str(self) -> &'static str {
        match self {
            Category::Identification => "identification",
            Category::Chapter => "chapter",
            Category::Verse => "verse",
            Category::Paragraph => "paragraph",
            Category::Character => "character",
            Category::Note => "note",
            Category::Milestone => "milestone",
            Category::Other => "other",
        }
    }
}

/// How a marker contributes to *cleaned* verse text (the `vref_text` walk).
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum TextRole {
    /// Drop the tag, keep the inner text. Most character markers (`\nd`, `\add`).
    Content,
    /// Skip the entire subtree via the `link` jump pointer (`\f`, `\x`).
    Excluded,
    /// Emit a single separating space; the marker carries no text of its own
    /// (paragraph/chapter boundaries).
    Boundary,
}

impl TextRole {
    pub fn as_str(self) -> &'static str {
        match self {
            TextRole::Content => "content",
            TextRole::Excluded => "excluded",
            TextRole::Boundary => "boundary",
        }
    }
}

/// Whether a marker expects an explicit `\xxx*` close.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Closing {
    /// Never closed (paragraph-level markers end at the next block).
    None,
    /// May be closed; if a block ends first we close implicitly + warn.
    Optional,
    /// Must be closed (most character/note markers).
    Required,
}

impl Closing {
    pub fn as_str(self) -> &'static str {
        match self {
            Closing::None => "none",
            Closing::Optional => "optional",
            Closing::Required => "required",
        }
    }
}

/// Everything the rest of the pipeline needs to know about one marker type.
#[derive(Clone, Copy, Debug)]
pub struct MarkerInfo {
    pub name: &'static str,
    pub category: Category,
    pub text_role: TextRole,
    pub closing: Closing,
    /// Element name when serializing to USX (e.g. `"para"`, `"char"`, `"note"`).
    pub usx_element: &'static str,
    /// `Some(replacement guidance)` when this marker is deprecated *in this
    /// version's table* (a `DeprecatedMarker` advisory); `None` otherwise. Version
    /// awareness is baked in at table-generation time, so the same marker can be
    /// current in one version's table and deprecated in a later one.
    pub deprecated: Option<&'static str>,
}

/// A resolved set of markers for one USFM version: the entry slice plus a
/// perfect-hash `name -> index` map. Both are `'static`, generated by `build.rs`.
pub struct MarkerTable {
    entries: &'static [MarkerInfo],
    index: &'static phf::Map<&'static str, u16>,
}

impl MarkerTable {
    /// The generated table for a given version.
    pub fn for_version(version: crate::Version) -> &'static MarkerTable {
        match version {
            crate::Version::V3_1 => &V3_1_TABLE,
            crate::Version::V3_2 => &V3_2_TABLE,
        }
    }

    /// Resolve a marker name (without the leading `\`, without any trailing `*`)
    /// to its id. O(1) via the perfect hash.
    ///
    /// Many USFM markers are a base plus a numeric level (`\q1`, `\mt2`, `\s3`)
    /// or, for table cells, a column / column-range (`\tc3`, `\tcr1-2`). Rather
    /// than enumerate every variant, the table stores the base (`q`, `mt`, `tc`,
    /// `tcr`, …) and we fall back to it by stripping a trailing `\d+(-\d+)?`.
    #[inline]
    pub fn lookup(&self, name: &str) -> Option<MarkerId> {
        if let Some(id) = self.index.get(name) {
            return Some(MarkerId(*id));
        }
        let base = strip_level_suffix(name);
        if base.len() != name.len()
            && let Some(id) = self.index.get(base)
        {
            return Some(MarkerId(*id));
        }
        // Recovery for a verse/chapter number glued to its marker with no
        // separating space, *including a sub-verse segment letter* — `\v3b`,
        // `\c2`. `strip_level_suffix` only peels a trailing `\d+(-\d+)?`, so a
        // segment letter (`v3b`) leaves the name unresolved above. Here the base
        // is the single leading `v`/`c` when a digit follows immediately; the
        // serializer's `verse_label` recovers the full label (`3b`) from the
        // marker name. Miss-path only: valid markers returned at the exact match.
        let bytes = name.as_bytes();
        if bytes.len() >= 2 && matches!(bytes[0], b'v' | b'c') && bytes[1].is_ascii_digit() {
            return self.index.get(&name[..1]).copied().map(MarkerId);
        }
        None
    }

    #[inline]
    pub fn info(&self, id: MarkerId) -> Option<&MarkerInfo> {
        self.entries.get(id.0 as usize)
    }

    /// Every entry, indexed by [`MarkerId::0`].
    ///
    /// Exists so a host can be handed the whole table once and then resolve marker
    /// ids itself — a packed tape carries `MarkerId`s, which are meaningless without
    /// it. `'static` because the tables are generated at build time.
    #[inline]
    pub fn entries(&self) -> &'static [MarkerInfo] {
        self.entries
    }

    #[inline]
    pub fn len(&self) -> usize {
        self.entries.len()
    }

    #[inline]
    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }

    /// Entries paired with their ids, in id order.
    pub fn iter(&self) -> impl Iterator<Item = (MarkerId, &'static MarkerInfo)> {
        self.entries
            .iter()
            .enumerate()
            .map(|(i, info)| (MarkerId(i as u16), info))
    }
}

/// Strip a trailing numeric level / column-range suffix: `q1`→`q`, `tcr1-2`→`tcr`,
/// `tc3-4`→`tc`. Leaves names without such a suffix (and milestones like `qt-s`,
/// which end in a letter) unchanged.
fn strip_level_suffix(name: &str) -> &str {
    let bytes = name.as_bytes();
    let mut end = bytes.len();
    // Optional `-<digits>` (column-span tail).
    let mut i = end;
    while i > 0 && bytes[i - 1].is_ascii_digit() {
        i -= 1;
    }
    if i > 0 && i < end && bytes[i - 1] == b'-' {
        end = i - 1;
    }
    // Leading `<digits>` of the level/column.
    let mut j = end;
    while j > 0 && bytes[j - 1].is_ascii_digit() {
        j -= 1;
    }
    // Only treat it as a suffix if a non-empty base remains.
    if j > 0 && j < end { &name[..j] } else { name }
}

include!(concat!(env!("OUT_DIR"), "/marker_tables.rs"));
